import { photoOrigins } from '../../../api/src/product/photo-origins.ts';

// Importer URLs identify immutable generated bytes, even after a product rename.
// Editable alt text and the current product slug are not image provenance.
export function productIllustration(image: { url: string } | null | undefined): boolean {
  return image != null && Object.hasOwn(photoOrigins, image.url);
}
